def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opps = []
    prev_bids = []
    aggressive_bids = []
    urgent_opps = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opps += 1
            prev = opp.get('previous_trace', {})
            if prev:
                bid = prev.get('bid')
                if bid is not None:
                    prev_bids.append(float(bid))
                    if float(bid) >= 100:
                        aggressive_bids.append(float(bid))

    if budget <= 0:
        return 0.0

    winner_slots = int(max(1, supply // WATER_REQ))
    scarcity = winner_slots <= 1

    if not alive_opps:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    second_prev = 0.0
    if len(prev_bids) >= 2:
        second_prev = sorted(prev_bids)[-2]

    my_urgent = hp <= 3 or no_water_days >= 1

    if my_urgent:
        target = highest_prev + 3.0 if highest_prev > 0 else 95.0
        if scarcity:
            target += 8.0
        return float(max(0.0, min(budget, target)))

    if scarcity:
        if highest_prev >= 135:
            bid = 38.0 if hp >= 7 and no_water_days == 0 else 112.0
        elif highest_prev >= 115:
            bid = highest_prev + 2.5
        elif highest_prev >= 90:
            bid = highest_prev + 4.0
        else:
            bid = 82.0

        if urgent_opps >= 2:
            bid += 6.0
        if hp >= 8 and no_water_days == 0 and budget < 250:
            bid *= 0.82
        return float(max(0.0, min(budget, bid)))

    bid = 46.0
    if highest_prev >= 120:
        bid = 72.0
    elif highest_prev >= 100:
        bid = 64.0
    elif highest_prev >= 70:
        bid = highest_prev * 0.78

    if urgent_opps >= 2:
        bid += 8.0
    if hp <= 5:
        bid += 10.0
    if no_water_days >= 1:
        bid += 14.0

    reserve_floor = 70.0 if hp >= 6 else 0.0
    bid = min(bid, max(0.0, budget - reserve_floor)) if budget > reserve_floor else min(budget, bid)
    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    # Alive opponents and yesterday bids (only immediate reaction)
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        # Conservative when alone
        cap = min(my_status['budget'], DAILY_SALARY * 0.4)
        return max(0.0, cap)

    yesterday_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass

    pressure = 0.0
    if yesterday_bids:
        pressure = max(yesterday_bids)

    # Supply pressure: with higher supply, we can bid slightly less; with lower supply, bid more.
    # Normalize supply to [0,1]
    denom = (MAX_SUPPLY - MIN_SUPPLY)
    if denom <= 0:
        supply_norm = 0.5
    else:
        supply_norm = (supply - MIN_SUPPLY) / denom
    if supply_norm < 0.0:
        supply_norm = 0.0
    if supply_norm > 1.0:
        supply_norm = 1.0

    # Base aggressiveness driven by our HP
    hp = float(my_status['hp'])
    if hp <= 2:
        hp_factor = 1.0
    elif hp <= 4:
        hp_factor = 0.85
    else:
        hp_factor = 0.65

    # If opponents were bidding near/above our salary yesterday, they are likely fighting for scarce water.
    if pressure >= DAILY_SALARY * 0.85:
        # Match their intensity but still slightly undercut to preserve budget
        target = pressure * 0.92
    elif pressure > 0.0:
        # Otherwise, bid enough to likely secure water without draining budget
        target = max(DAILY_SALARY * (0.45 + 0.2 * (1.0 - supply_norm)), pressure * 0.75)
    else:
        target = DAILY_SALARY * (0.5 + 0.25 * (1.0 - supply_norm))

    # Adjust with HP factor
    target = target * hp_factor

    # Ensure we don't bid more than budget
    budget = float(my_status['budget'])
    if budget <= 0.0:
        return 0.0

    # Soft cap: don't exceed a fraction of budget early/midgame
    # (episode_days=10, meta-round medium; keep some reserve)
    soft_cap = budget * 0.6
    final_bid = min(target, soft_cap, budget)

    # Avoid negative/zero bids if we can afford a meaningful bid
    if final_bid < 1.0:
        # If extremely low budget, bid whatever remains
        final_bid = min(budget, DAILY_SALARY * 0.15)

    # Clamp to non-negative
    if final_bid < 0.0:
        final_bid = 0.0

    return float(final_bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not yesterday_bids:
        bid = DAILY_SALARY * 0.7
    else:
        avg_prev = sum(yesterday_bids) / len(yesterday_bids)
        if supply < 18:
            bid = min(my_status['budget'], max(avg_prev + 5, DAILY_SALARY * 1.1))
        else:
            bid = min(my_status['budget'], max(avg_prev * 0.9, DAILY_SALARY * 0.6))

    if my_status['hp'] < 3:
        bid = min(my_status['budget'], DAILY_SALARY * 1.2)

    return float(min(my_status['budget'], bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']
    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)
    yesterday_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
    max_prev_bid = max(yesterday_bids) if yesterday_bids else 0
    if no_water_days > 0 or hp <= 2:
        bid = min(budget, max(DAILY_SALARY * 0.9, max_prev_bid + 1))
    else:
        if max_prev_bid > DAILY_SALARY * 0.85:
            if hp > 4:
                bid = min(budget, DAILY_SALARY * 0.3)
            else:
                bid = min(budget, max(DAILY_SALARY * 0.6, max_prev_bid - 5))
        else:
            bid = min(budget, max(DAILY_SALARY * 0.4, max_prev_bid + 2))
    max_possible = int(supply // WATER_REQ) * DAILY_SALARY * 0.8
    bid = min(bid, max_possible, budget)
    return max(0, bid)
